diff --git a/tests/Invoke-Mirror.Tests.ps1 b/tests/Invoke-Mirror.Tests.ps1
index 3333333..4444444 100644
--- a/tests/Invoke-Mirror.Tests.ps1
+++ b/tests/Invoke-Mirror.Tests.ps1
@@ -1,3 +1,12 @@
 Describe 'Invoke-Mirror exit classification' {
+    It 'snapshots the native exit before emitting diagnostics' {
+        $source = Get-Content -Raw src/Invoke-Mirror.ps1
+        $source.IndexOf('$copyExit = $LASTEXITCODE') | Should -BeLessThan $source.IndexOf('Write-Verbose')
+        $source | Should -Match 'if \(\$copyExit -le 7\)'
+        $source | Should -Not -Match '& where\.exe'
+    }
+    It 'keeps the robocopy success boundary' {
+        (0 -le 7) | Should -BeTrue
+        (7 -le 7) | Should -BeTrue
+        (8 -le 7) | Should -BeFalse
+    }
 }
